@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

/* ---- Semantic design tokens (light) ---- */
:root {
  --bg: #f8fafd;
  --surface: #ffffff;
  --surface-2: #f2f5f9;
  --surface-hover: #f0f4f9;
  --surface-sunken: #eaeef6;
  --border: #e1e3e6;
  --border-strong: #c8ccd0;
  --ink: #1f1f1f;
  --ink-secondary: #444746;
  --ink-muted: #5e6266;
  --ink-faint: #8a8f95;
  --accent: #0b57d1;
  --accent-hover: #0842a0;
  --accent-soft: #e8f0fe;
  --on-accent: #ffffff;
  --selected: #c2e7ff;
  --selected-hover: #aeddff;
  --nav-selected: #d3e3fd;
  --nav-hover: #e9eef6;
  --star: #f9ab00;
  --unread-dot: #0b57d1;
  --shadow-color: 60 64 67;
  --cat-primary: #1a73e8;
  --cat-social: #1e8e3e;
  --cat-promotions: #1a73e8;
  --cat-updates: #d93025;
  --green: #188038;
  --red: #d93025;
  --amber: #f9ab00;
  --scrollbar: #c4c7c5;
}

.dark {
  --bg: #131314;
  --surface: #1e1f20;
  --surface-2: #28292a;
  --surface-hover: #2d2e30;
  --surface-sunken: #1a1a1b;
  --border: #333438;
  --border-strong: #444649;
  --ink: #e3e3e3;
  --ink-secondary: #c4c7c5;
  --ink-muted: #9aa0a6;
  --ink-faint: #7c8085;
  --accent: #a8c7fa;
  --accent-hover: #c2dbff;
  --accent-soft: #1f2a3d;
  --on-accent: #062e6f;
  --selected: #004a77;
  --selected-hover: #005a8f;
  --nav-selected: #0842a0;
  --nav-hover: #2a2b2d;
  --star: #fdd663;
  --unread-dot: #a8c7fa;
  --shadow-color: 0 0 0;
  --cat-primary: #8ab4f8;
  --cat-social: #81c995;
  --cat-promotions: #8ab4f8;
  --cat-updates: #f28b82;
  --green: #81c995;
  --red: #f28b82;
  --amber: #fdd663;
  --scrollbar: #5f6368;
}

@theme inline {
  --color-canvas: var(--bg);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-surface-hover: var(--surface-hover);
  --color-surface-sunken: var(--surface-sunken);
  --color-line: var(--border);
  --color-line-strong: var(--border-strong);
  --color-ink: var(--ink);
  --color-ink-secondary: var(--ink-secondary);
  --color-ink-muted: var(--ink-muted);
  --color-ink-faint: var(--ink-faint);
  --color-accent: var(--accent);
  --color-accent-hover: var(--accent-hover);
  --color-accent-soft: var(--accent-soft);
  --color-on-accent: var(--on-accent);
  --color-selected: var(--selected);
  --color-selected-hover: var(--selected-hover);
  --color-nav-selected: var(--nav-selected);
  --color-nav-hover: var(--nav-hover);
  --color-star: var(--star);
  --color-unread: var(--unread-dot);
  --color-brand-green: var(--green);
  --color-brand-red: var(--red);
  --color-brand-amber: var(--amber);
}

* {
  border-color: var(--border);
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: "Google Sans Text", "Roboto", -apple-system, BlinkMacSystemFont,
    "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
  overflow: hidden;
  -webkit-tap-highlight-color: transparent;
}

.font-display {
  font-family: "Google Sans", "Product Sans", "Roboto", sans-serif;
}

/* Scrollbars */
.scroll-thin {
  scrollbar-width: thin;
  scrollbar-color: var(--scrollbar) transparent;
}
.scroll-thin::-webkit-scrollbar {
  width: 12px;
  height: 12px;
}
.scroll-thin::-webkit-scrollbar-thumb {
  background-color: var(--scrollbar);
  border-radius: 999px;
  border: 3px solid var(--bg);
}
.scroll-thin::-webkit-scrollbar-thumb:hover {
  background-color: var(--border-strong);
}
.scroll-thin::-webkit-scrollbar-track {
  background: transparent;
}

/* Elevation helpers */
.elev-1 {
  box-shadow: 0 1px 2px 0 rgb(var(--shadow-color) / 0.3),
    0 1px 3px 1px rgb(var(--shadow-color) / 0.15);
}
.elev-2 {
  box-shadow: 0 1px 3px 0 rgb(var(--shadow-color) / 0.3),
    0 4px 8px 3px rgb(var(--shadow-color) / 0.15);
}
.elev-3 {
  box-shadow: 0 4px 8px 0 rgb(var(--shadow-color) / 0.3),
    0 8px 24px 6px rgb(var(--shadow-color) / 0.18);
}

/* Focus ring */
.ring-focus:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* Message body typography */
.mail-body {
  font-size: 14px;
  line-height: 1.6;
  color: var(--ink);
  word-break: break-word;
}
.mail-body p {
  margin: 0 0 14px;
}
.mail-body a {
  color: var(--accent);
  text-decoration: none;
}
.mail-body a:hover {
  text-decoration: underline;
}
.mail-body ul,
.mail-body ol {
  margin: 0 0 14px;
  padding-left: 22px;
}
.mail-body li {
  margin-bottom: 4px;
}
.mail-body h1,
.mail-body h2,
.mail-body h3 {
  margin: 4px 0 10px;
  line-height: 1.3;
}
.mail-body blockquote {
  border-left: 2px solid var(--border-strong);
  margin: 0 0 14px;
  padding-left: 14px;
  color: var(--ink-muted);
}
.mail-body hr {
  border: none;
  border-top: 1px solid var(--border);
  margin: 18px 0;
}
.mail-body .btn-cta {
  display: inline-block;
  background: var(--accent);
  color: #fff;
  padding: 10px 22px;
  border-radius: 8px;
  font-weight: 600;
  text-decoration: none !important;
}
.mail-body .muted {
  color: var(--ink-muted);
  font-size: 12px;
}
.dark .mail-body .btn-cta {
  color: #062e6f;
}

/* Animations */
@keyframes pop-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}
.animate-pop {
  animation: pop-in 0.16s cubic-bezier(0.2, 0, 0, 1);
}

@keyframes slide-up {
  from {
    opacity: 0;
    transform: translateY(16px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.animate-slide-up {
  animation: slide-up 0.2s cubic-bezier(0.2, 0, 0, 1);
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
.animate-fade {
  animation: fade-in 0.15s ease-out;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
.animate-spin-slow {
  animation: spin 1s linear infinite;
}

/* Row leave animation */
@keyframes row-collapse {
  to {
    opacity: 0;
    transform: translateX(24px);
  }
}

input,
button,
textarea {
  font-family: inherit;
}

::selection {
  background: var(--accent-soft);
}

